and $\overline{T}=\overline{T}(w)$
such that if $t\geq \overline{T}$ and $\rho(x,t) < \overline{\rho} \sqrt{t}$ then
\begin{equation}
\vol(B(x,t,\rho(x,t))) \: < \: w \rho^3(x,t).
\end{equation}
\end{lemma}

