\begin{theorem}[existence for thick--thin geometry]
  \bpnode{thm:kl-thin-part-graph-manifold-existence-thick-thin-geometry}
\label{thm:kl-thin-part-graph-manifold-existence-thick-thin-geometry}
  \source{kleiner-lott}
